pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {SimpleWallet} from "../src/SimpleWallet.sol";

contract InvMutTest is Test {
    SimpleWallet c;
    function setUp() public { c = new SimpleWallet(); }

    function testFuzz_property(uint256 fundAmount, uint256 withdrawAmount, address actor) public {
        vm.assume(actor != address(0) && actor != address(c));
        fundAmount = bound(fundAmount, 1, 1e30);
        withdrawAmount = bound(withdrawAmount, 0, 1e60);

        address owner = c.owner();
        vm.deal(owner, fundAmount);
        vm.prank(owner);
        (bool okFund, ) = address(c).call{value: fundAmount}("");
        assertTrue(okFund);

        vm.deal(actor, 1);
        vm.prank(owner);
        bool ok;
        try c.withdraw(withdrawAmount) { ok = true; } catch { ok = false; }

        assertTrue(
            (withdrawAmount > address(c).balance + withdrawAmount ? false : !ok) ||
            withdrawAmount > 0, // placeholder never used
            "placeholder"
        );
    }
}
